import{_ as t}from"./chunks/76f1eccbe7ad8b01c28f.CfBJWXqu.js";import{_ as o,o as a,c as i,a6 as n}from"./chunks/framework.CnPv4DE1.js";const f=JSON.parse('{"title":"How I Hunt For Viral Ideas (A 5 Minute Reading Habit)","description":"","frontmatter":{"title":"How I Hunt For Viral Ideas (A 5 Minute Reading Habit)","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/how-i-read-books-for-maximum-intelligence-5-minute-habit.md","filePath":"en/letters/how-i-read-books-for-maximum-intelligence-5-minute-habit.md"}'),r={name:"en/letters/how-i-read-books-for-maximum-intelligence-5-minute-habit.md"};function s(l,e,h,p,u,d){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="how-i-hunt-for-viral-ideas-a-5-minute-reading-habit" tabindex="-1">How I Hunt For Viral Ideas (A 5 Minute Reading Habit) <a class="header-anchor" href="#how-i-hunt-for-viral-ideas-a-5-minute-reading-habit" aria-label="Permalink to &quot;How I Hunt For Viral Ideas (A 5 Minute Reading Habit)&quot;">​</a></h1><p>Dan Koe · 2023-03-25 · <a href="https://thedankoe.com/letters/how-i-read-books-for-maximum-intelligence-5-minute-habit/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/how-i-read-books-for-maximum-intelligence-5-minute-habit">返回中文译文</a></p><p><a href="https://www.youtube.com/embed/YU0OKEvlH-8?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>Books allow you to explore the world that someone else has interpreted.</p><p>Books allow you to try on different worldviews to see situations in a new light.</p><p>Books present big, powerful, and time-tested ideas that can change the way you think. And by changing the way you think, you change the way you act, which determines the entirety of your future.</p><p>For the longest time, I would force myself to read entire books.</p><p>I’d never finish, of course, because they failed to hold my attention after some time.</p><p>I’ve grown busier over the years.</p><p>Business projects can be endless if I don’t say “no.”</p><p>I have fitness and self-actualization goals that demand a consistent chunk out of my days.</p><p>I’m dedicating more time to dating and relationships because I’ve put it off to build other areas of my life.</p><p>I understand the power of reading, but it’s an afterthought nowadays.</p><p>Sure, I can schedule 30 minutes here and there for a good book, but I’ve never seemed to sustain that habit. Which is sad because a reading habit keeps your mind flowing with ideas. It’s hard to remain stagnant when endless solutions are at the top of your mind.</p><p>In this letter I want to give you the process I’ve used to:</p><ul><li>Incorporate novel information into my day (to expand my mind and maintain the zest I have for life)</li><li>Capture ideas that I can use to fuel my own writing, articulation, and understanding.</li><li>Have it take less than 5 minutes each day so I can sustain my reading habit</li></ul><p>Let’s dig in.</p><h2 id="set-an-intention" tabindex="-1">Set An Intention <a class="header-anchor" href="#set-an-intention" aria-label="Permalink to &quot;Set An Intention&quot;">​</a></h2><p>Humans are goal-oriented creatures.</p><p>We interpret information, conversations, and happenings from our individual perspectives.</p><p>At the root of that perspective is a series of goals, problems, and beliefs surrounding those goals or problems.</p><p>For most, this perspective is mindless and firm.</p><p>That is, it was conditioned into their head by society and culture.</p><p>Most people are automatons with the goal of going to college, getting a job, and retiring at 65.</p><p>So, they perceive the world through that lens.</p><p>They only <em>see</em> what helps them achieve those goals.</p><p>Any information that does not align with their perspective goes unseen.</p><p>Meaning 99% of life itself goes unseen.</p><p>If you want to experience the depth and opportunity that lies beyond surface-level living:</p><ul><li>Set a meaningful goal for your future</li><li>Remind yourself of that goal to hold it in the back of your mind</li><li>Notice how you interpret life in a new light and your decisions begin to align with your goals</li></ul><p>When you read a book you will begin to notice potential solutions to your problems, no matter the book topic.</p><h2 id="hunting-for-ideas" tabindex="-1">Hunting For Ideas <a class="header-anchor" href="#hunting-for-ideas" aria-label="Permalink to &quot;Hunting For Ideas&quot;">​</a></h2><p>Our ancestors would hunt for food and resources.</p><p>But we do not live in that world.</p><p>We don’t have to worry about the threats that they did, and our survival needs have transcended the physical plane of existence into the mental.</p><p>Instead, great and memorable humans hunt for ideas.</p><p>To “hunt” is to reap meaningful dopamine from the web of information that we have access to online and off.</p><p>You do not hunt in the known. You explore the unknown to make novel discoveries.</p><ul><li>Read the books that challenge you.</li><li>Read the books that pique your curiosity.</li><li>Read the books that you’ve been putting off reading.</li></ul><p>The ones that have you place one foot in the unknown.</p><p>That way, the words pass through the middle of the right and left hemispheres of the brain.</p><p>The right hemisphere controls what you know while the left controls what is unknown.</p><p>When information passes through the “middle,” at the edge of your understanding, your nervous system signals to you that this is a meaningful event. A novel discovery in the making. A cosmic conflict reflected in your psyche that when resolved births creative emergence. In our case, a new idea, insight, or perception.</p><p>Certain books are so gripping because you are realizing the potential for your life. The ideas act as the raw material that you can use to sculpt the musical illustration that is your self-written story.</p><h2 id="creativity-is-playing-with-mental-legos" tabindex="-1">Creativity Is Playing With Mental Legos <a class="header-anchor" href="#creativity-is-playing-with-mental-legos" aria-label="Permalink to &quot;Creativity Is Playing With Mental Legos&quot;">​</a></h2><p>You are forgetful.</p><p>We all are.</p><p>So, create a commonplace in a handy notebook or app in your phone.</p><p>You need a place to capture the ideas that stick out to you the most.</p><p>That’s the first step.</p><p>The second is to stop reading.</p><p>Seriously, once you find a novel idea put down the book.</p><p>You don’t read a book to remember every single word. You read a book to find a life-changing idea and implement it into your life.</p><p>Once you find and note the novel idea:</p><ul><li><strong>Contemplate the utility of the idea.</strong> How does it relate to your life in more ways than one?</li><li><strong>Apply it to your goals.</strong> How can the idea aid in the improvement of your mind, body, or business?</li><li><strong>Attempt to turn it into your own.</strong> How can you rephrase the idea from your perspective?</li></ul><p>If you don’t have an idea development system, <a href="https://7daystogeniusideas.com/" target="_blank" rel="noreferrer">you can download mine here in the form of a 7 day creative challenge.</a></p><p>In the meantime, here’s how you can attempt to turn it into your own idea:</p><p>Think about your goals.</p><p>Think about your current problems.</p><p>Think about your personal experiences.</p><p>Think about who you are and who you are becoming.</p><p>Then, frame the idea from your thoughts on any of the above.</p><p>I came across this fantastic idea the other day from Johann Wolfgang von Goethe:</p><blockquote><p>Music is liquid architecture; architecture is frozen music.</p></blockquote><p>If I contemplate my goals of writing and publishing a book, my reworded idea would be along the lines of:</p><blockquote><p>Books are paper sculptures. Writing is the clay and articulation is the chisel.</p></blockquote><p>I’m sure it could be better or expanded, but you’d be surprised how powerful this can get with the ideas you store with time.</p><p><strong>The lesson:</strong></p><p>It’s better to focus on one idea instead of being flooded by thousands. Go deep. Sit with it. Contemplate it. And avoid getting trapped in the mental masturbation cycle of hoarding surface-level ideas that have no practical application to your life.</p><p>Read for 5 minutes.</p><p><em>If an idea doesn’t grip you, choose a different book or skip to a different chapter.</em></p><h2 id="the-law-of-use" tabindex="-1">The Law Of Use <a class="header-anchor" href="#the-law-of-use" aria-label="Permalink to &quot;The Law Of Use&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>Most people don’t need more advice.</p><p>They need more powerful ideas to shape their worldview and frame their decision-making.</p><p>That way they make better choices, figure it out for themselves, and reap the dopamine that comes from trial and error induced progress.</p><p>The problem is that to reach powerful ideas you have to expand your mind to the point of understanding them.</p><p>To understand, ideas must meet reality.</p><p>You have to put the ideas you’ve gathered to use and solidify them through direct experience.</p><p>Only then can you <a href="https://thedankoe.com/life-is-hard-get-used-to-it-the-way-to-mental-mastery/" target="_blank" rel="noreferrer">raise your level of mind</a> to access the next stage of ideas.</p><p>Like bodybuilding but with mental capacity.</p><p>Progressive overload still applies.</p><p>Drowning yourself in surface-level “how to” advice is like lifting 5-pound dumbbells for the entirety of your life and expecting to build mental muscle.</p><p>To brush your ideas up against reality:</p><ul><li>Write or journal to dive into the depths of <em>one</em> idea</li><li>Start with a common problem, steps or a story to overcome it, and the transformation that occurs from doing so (this is the structure of both human behavior, storytelling, and content marketing)</li><li>Sit with the ideas that stem from your writing and refine them</li></ul><p>My favorite way of incorporating this mental expansion process is, of course, to <a href="https://thedankoe.com/the-future-of-the-creator-economy-my-bold-prediction/" target="_blank" rel="noreferrer">contribute to humanity through the creator economy</a>.</p><p>Humans survive on a conceptual level, and this phenomenon is not limited to feeling threatened when someone challenges your beliefs.</p><p>We seek to reproduce through the transfer of ideas.</p><p>On the negative end, ideologues and zealots force their beliefs on you.</p><p>On the positive end, creators share their personal experiences and raise the collective well-being (and make a living doing so).</p><p>By writing long-form content, like a newsletter, you effectively:</p><ul><li>Deconstruct the idea you gathered on your hunt</li><li>Reconnect the dots through original writing</li><li>Deconstruct your own writing into a plethora of ideas</li><li>Repeat the process and increase your mental capacity</li></ul><p>In hyper-practical terms: write a newsletter or Twitter thread, break those down into tweets, and turn your tweets back into newsletters or threads.</p><p>That’s my content strategy in a nutshell.</p><p>I repurpose my newsletter, threads, and tweets to all platforms (and use my <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a> system to do it).</p><p>Not only does it prevent your mind from clogging up and sticking on one menial problem, but you impact millions of people along the way.</p><p>You will know 1000 people in your life.</p><p>They will know 1000 in their lives.</p><p>1 billion people are 2 people that spread your ideas away from you.</p><p>Yes, the math on this is correct (even though I failed out of math).</p><p>1000 x 1000 = 1,000,000 people that each have access to 1000 people in their lifetime = 1,000,000,000</p><p>(I took this idea from Peterson btw).</p><p>Don’t underthink your potential impact.</p><p>Set an intention.</p><p>Hunt for ideas.</p><p>Play with mental legos.</p><p>Distribute your ideas.</p><p>– Dan Koe</p><p>P.S. When you’re ready:</p><p>There are free productivity tools, creativity challenges, and previous letters <a href="https://thedankoe.com/" target="_blank" rel="noreferrer">on my site.</a></p><p>You can also find a paid masterclass to productize yourself in the new economy, learn high-impact writing, and a community with 180+ strategies and courses to build your own thing.</p>',111)])])}const y=o(r,[["render",s]]);export{f as __pageData,y as default};
